(30661, 'Luke 1:65', 'Luke', 1, 65, 'ټول ګاونډیان ووېرېدل او د یهودیې په ټوله غرنۍ سیمه کې خلکو د دې شیانو په هکله خبرې کولې.', 'تول ګاوندیان ووېرېدل او د یهودیې په توله غرنی سیمه کې خلکو د دې شیانو په هکله خبرې کولې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_65.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30662, 'Luke 1:66', 'Luke', 1, 66, 'هرچا چې دا خبره اورېدله، نو د هغې په هکله یې فکر کاوه او پوښتنه یې کوله: «د دې ماشوم څخه به څه جوړ شي؟» ځکه چې د څښتن لاس د هغه په سر باندې ؤ. د زکریا پېشګويي', 'هرچا چې دا خبره اورېدله، نو د هغې په هکله یې فکر کاوه او پوشتنه یې کوله: «د دې ماشوم چخه به چه جور شی؟» جکه چې د چشتن لاس د هغه په سر باندې و. د زکریا پېشګویی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_66.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30663, 'Luke 1:67', 'Luke', 1, 67, 'د یحیی پلار زکریا د روح القدس نه ډک شو او د خدای پیغام یې ورکړ:', 'د یحیی پلار زکریا د روح القدس نه دک شو او د خدای پیغام یې ورکر:', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_67.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30664, 'Luke 1:68', 'Luke', 1, 68, '«ثنا او صفت دې وي څښتن ته چې دی خدای د اسراییلو ځکه راغی چې وکړي مرسته د خپل قوم سره چې کړي ازاد هغوی', '«ثنا او صفت دې وی چشتن ته چې دی خدای د اسراییلو جکه راغی چې وکری مرسته د خپل قوم سره چې کری ازاد هغوی', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_68.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30665, 'Luke 1:69', 'Luke', 1, 69, 'هغه پیدا کړ مونږ ته زورور ژغورونکی د اولادې نه د داود چې خدمتګار یې ؤ خپل', 'هغه پیدا کر مونز ته زورور ژغورونکی د اولادې نه د داود چې خدمتګار یې و خپل', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_69.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30666, 'Luke 1:70', 'Luke', 1, 70, 'لکه څنګه چې پخوا یې وو ویلي په خوله د سپېڅلو پخوانیو پیغمبرانو', 'لکه چنګه چې پخوا یې وو ویلی په خوله د سپېچلو پخوانیو پیغمبرانو', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_70.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30667, 'Luke 1:71', 'Luke', 1, 71, 'چې مو خلاص کړي د خپلو دښمنانو ځینې د هغو خلکو څخه چې کوي کرکه له مونږ', 'چې مو خلاص کری د خپلو دشمنانو جینې د هغو خلکو چخه چې کوی کرکه له مونز', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_71.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30668, 'Luke 1:72', 'Luke', 1, 72, 'رحم به وکړي هغه زمونږ نیکونو باندې او رایادوي به خپل سپېڅلی لوظ', 'رحم به وکری هغه زمونز نیکونو باندې او رایادوی به خپل سپېچلی لوظ', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_72.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30669, 'Luke 1:73', 'Luke', 1, 73, 'هغه قسم چې ؤ خوړلی هغه زمونږ د نیکه ابراهیمه سره', 'هغه قسم چې و خورلی هغه زمونز د نیکه ابراهیمه سره', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_73.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30670, 'Luke 1:74', 'Luke', 1, 74, 'چې به کړي خلاص هغه مونږ له دښمنانو ځینې چې بې له وېرې وکړو مونږه خدمت د هغه', 'چې به کری خلاص هغه مونز له دشمنانو جینې چې بې له وېرې وکرو مونزه خدمت د هغه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_74.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30671, 'Luke 1:75', 'Luke', 1, 75, 'په ټول ژوندون کې د پاکۍ او عدالت سره', 'په تول ژوندون کې د پاکی او عدالت سره', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_75.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30672, 'Luke 1:76', 'Luke', 1, 76, 'او ای ماشومه زما ته به یادېږې پیغمبر د خدای تعالی ځکه چې ځې به له څښتنه مخکې چې کړې تیاره لاره ته د هغه دپاره', 'او ای ماشومه زما ته به یادېزې پیغمبر د خدای تعالی جکه چې جې به له چشتنه مخکې چې کرې تیاره لاره ته د هغه دپاره', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_76.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30673, 'Luke 1:77', 'Luke', 1, 77, 'چې په دې پوه کړې قوم د هغه چې دوی به ومومي خلاصون د خپلو ګناهونو په بخښلو سره', 'چې په دې پوه کرې قوم د هغه چې دوی به ومومی خلاصون د خپلو ګناهونو په بخشلو سره', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_77.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30674, 'Luke 1:78', 'Luke', 1, 78, 'زمونږ د خدای د رحم او مهربانۍ په سبب په مونږ را وبه خېژي لمر د سهار پاس له اسمانه څخه', 'زمونز د خدای د رحم او مهربانی په سبب په مونز را وبه خېژی لمر د سهار پاس له اسمانه چخه', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_78.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237836, 1761237836),
(30675, 'Luke 1:79', 'Luke', 1, 79, 'ترڅو چې راولي رڼا په هغو خلکو باندې چې تېروي ژوند په تیارو کې د مرګ او برابر کړي قدمونه زمونږ د سولې او سلامتۍ په لاره»', 'ترچو چې راولی رنا په هغو خلکو باندې چې تېروی ژوند په تیارو کې د مرګ او برابر کری قدمونه زمونز د سولې او سلامتی په لاره»', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_79.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30676, 'Luke 1:80', 'Luke', 1, 80, 'هغه ماشوم غټېده او په روحاني توګه قوي کېده او تر هغه وخته پورې په دښته کې اوسېده، ترڅو د اسراییلو خلکو ته په څرګنده توګه ورښکاره شو.', 'هغه ماشوم غتېده او په روحانی توګه قوی کېده او تر هغه وخته پورې په دشته کې اوسېده، ترچو د اسراییلو خلکو ته په چرګنده توګه ورشکاره شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Luke_1_80.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30677, 'Revelation 9:1', 'Revelation', 9, 1, 'بیا پنځمې فرښتې خپل سرنی وواهه او ما یو ستوری ولیده چې د اسمان نه ځمکې ته راولوېد او هغه ستوري ته د ځمکې د تل د لارې کیلي ورکړل شوې وه.', 'بیا پنجمې فرشتې خپل سرنی وواهه او ما یو ستوری ولیده چې د اسمان نه جمکې ته راولوېد او هغه ستوری ته د جمکې د تل د لارې کیلی ورکرل شوې وه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_1.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30678, 'Revelation 9:2', 'Revelation', 9, 2, 'هغه په دې کیلي باندې د ځمکې د تل لاره خلاصه کړه او د هغې کندې نه د یو لوی داش د لوګي په شان لوګی راپورته شو او لمر او هوا د هغه داش د لوګي له امله تیاره شوه.', 'هغه په دې کیلی باندې د جمکې د تل لاره خلاصه کره او د هغې کندې نه د یو لوی داش د لوګی په شان لوګی راپورته شو او لمر او هوا د هغه داش د لوګی له امله تیاره شوه.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_2.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30679, 'Revelation 9:3', 'Revelation', 9, 3, 'بیا د لوګي نه ځمکې ته ملخان راووتل او هغوی ته لکه د لړمانو په شان قدرت ورکړل شو.', 'بیا د لوګی نه جمکې ته ملخان راووتل او هغوی ته لکه د لرمانو په شان قدرت ورکرل شو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_3.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30680, 'Revelation 9:4', 'Revelation', 9, 4, 'هغوی ته وویل شول چې واښو، ونو او بوټو ته زیان ونه رسوي، بلکې یوازې هغو خلکو ته زیان ورسوي چې د هغو په تندیو باندې د خدای مهر نه وي لګېدلی.', 'هغوی ته وویل شول چې واشو، ونو او بوتو ته زیان ونه رسوی، بلکې یوازې هغو خلکو ته زیان ورسوی چې د هغو په تندیو باندې د خدای مهر نه وی لګېدلی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_4.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30681, 'Revelation 9:5', 'Revelation', 9, 5, 'ملخانو ته اجازه ورکړل شوه چې هغه خلکو ته پنځه میاشتې عذاب ورکړي، داسې عذاب چې د لړم د چیچلو په شان وي، خو د هغوی د وژلو اجازه ورته نه وه ورکړل شوې.', 'ملخانو ته اجازه ورکرل شوه چې هغه خلکو ته پنجه میاشتې عذاب ورکری، داسې عذاب چې د لرم د چیچلو په شان وی، خو د هغوی د وژلو اجازه ورته نه وه ورکرل شوې.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30682, 'Revelation 9:6', 'Revelation', 9, 6, 'په هغو ورځو کې به دغه کسان مرګ وغواړي خو مرګ به ورته نه راځي. هغوی به د مرګ په ارمان وي، خو مرګ به ورڅخه تښتي.', 'په هغو ورجو کې به دغه کسان مرګ وغواری خو مرګ به ورته نه راجی. هغوی به د مرګ په ارمان وی، خو مرګ به ورچخه تشتی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30683, 'Revelation 9:7', 'Revelation', 9, 7, 'دا ملخان د هغو اسونو په شان ښکاره کېدل چې جنګ ته تیار وي. د هغوی په سرونو باندې د سرو زرو په شان تاجونه وو او مخونه یې د انسان د مخونو په شان وو.', 'دا ملخان د هغو اسونو په شان شکاره کېدل چې جنګ ته تیار وی. د هغوی په سرونو باندې د سرو زرو په شان تاجونه وو او مخونه یې د انسان د مخونو په شان وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30684, 'Revelation 9:8', 'Revelation', 9, 8, 'د هغوی ویښتان د ښځو د ویښتانو په شان وو او غاښونه یې د زمریو د غاښونو په شان وو.', 'د هغوی ویشتان د شجو د ویشتانو په شان وو او غاشونه یې د زمریو د غاشونو په شان وو.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_8.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30685, 'Revelation 9:9', 'Revelation', 9, 9, 'هغوی لکه د اوسپنې څخه جوړ شویو زغرو کالي اغوستې وو او د هغوی د وزرونو اواز د اسونو او ډېرو جنګي ګاډیو د غړمبار په شان ؤ چې د جنګ میدان ته ځغلي.', 'هغوی لکه د اوسپنې چخه جور شویو زغرو کالی اغوستې وو او د هغوی د وزرونو اواز د اسونو او دېرو جنګی ګادیو د غرمبار په شان و چې د جنګ میدان ته جغلی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_9.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30686, 'Revelation 9:10', 'Revelation', 9, 10, 'د هغوی لکۍ‌ګانو لکه د لړمانو د لکیو په شان نېشونه لرل چې د دې قدرت یې درلود چې په خپلو لکۍ‌ګانو سره پنځه میاشتې خلک وځوروي.', 'د هغوی لکی‌ګانو لکه د لرمانو د لکیو په شان نېشونه لرل چې د دې قدرت یې درلود چې په خپلو لکی‌ګانو سره پنجه میاشتې خلک وجوروی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
(30687, 'Revelation 9:11', 'Revelation', 9, 11, 'د هغوی پاچا یوه فرښته وه چې د ځمکې د تل د کندې مشره وه چې په عبراني ژبه کې د هغې نوم ابدون او په یوناني ژبه کې آپولیون ؤ چې معنی یې تباه کوونکې دی.', 'د هغوی پاچا یوه فرشته وه چې د جمکې د تل د کندې مشره وه چې په عبرانی ژبه کې د هغې نوم ابدون او په یونانی ژبه کې اپولیون و چې معنی یې تباه کوونکې دی.', 'NT', 'afghan2023', 'afghan', 'audio/afghan2023/Revelation_9_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237836, 1761237836),
